 "content": "def transform(grid):
    """Complete the vertical color guides through the segmented horizontal bands."""
    out = [row[:] for row in grid]
    h, w = len(out), len(out[0])
    marker_cols = {c for r in range(max(0, h - 4), h)
                   for c, value in enumerate(out[r]) if value != 0}

    for c in marker_cols:
        if c == 0 or c == w - 1:
            continue
        # The guide's color is the color of its lowest existing marker cell.
        guide_color = next((out[r][c] for r in range(h - 1, -1, -1) if out[r][c]), None)
        if guide_color is None:
            continue
        # A band is identified by a single missing cell between same-colored
        # horizontal runs, aligned with this vertical guide.
        events = []
        for r in range(h - 4):
            left, right = out[r][c - 1], out[r][c + 1]
            if out[r][c] == 0 and left != 0 and left == right:
                events.append((r, left))
        if not events:
            continue
        # Above/between bands, the vertical segment takes the color of the
        # next band; the segment below the final band retains guide color.
        for i, (r, color) in enumerate(events):
            top = 0 if i == 0 else events[i - 1][0] + 1
            for rr in range(top, r + 1):
                out[rr][c] = color
        for rr in range(events[-1][0] + 1, h):
            out[rr][c] = guide_color
    return out

